54	namespace ix
55	{
56	    const int WebSocketTransport::kDefaultPingIntervalSecs(-1);
57	    const bool WebSocketTransport::kDefaultEnablePong(true);
58	    const int WebSocketTransport::kClosingMaximumWaitingDelayInMs(300);
59	    constexpr size_t WebSocketTransport::kChunkSize;
60	
61	    WebSocketTransport::WebSocketTransport()
62	        : _useMask(true)
63	        , _blockingSend(false)
64	        , _sendTimeoutSecs(-1)
65	        , _fragmentedMessageKind(MessageKind::MSG_TEXT)
66	        , _receivedMessageCompressed(false)
67	        , _protocolError(false)
68	        , _readyState(ReadyState::CLOSED)
69	        , _closeCode(WebSocketCloseConstants::kInternalErrorCode)
70	        , _closeWireSize(0)
71	        , _closeRemote(false)
72	        , _enablePerMessageDeflate(false)
73	        , _requestInitCancellation(false)
74	        , _closingTimePoint(std::chrono::steady_clock::now())
75	        , _enablePong(kDefaultEnablePong)
76	        , _pingIntervalSecs(kDefaultPingIntervalSecs)
77	        , _pongReceived(false)
78	        , _setCustomMessage(false)
79	        , _kPingMessage("ixwebsocket::heartbeat")
80	        , _pingType(SendMessageKind::Ping)
81	        , _pingCount(0)
82	        , _lastSendPingTimePoint(std::chrono::steady_clock::now())
83	    {
84	        setCloseReason(WebSocketCloseConstants::kInternalErrorMessage);
85	        _readbuf.resize(kChunkSize);
86	    }
87	
88	    WebSocketTransport::~WebSocketTransport()
89	    {
90	        ;
91	    }
92	
93	    void WebSocketTransport::configure(
94	        const WebSocketPerMessageDeflateOptions& perMessageDeflateOptions,
95	        const SocketTLSOptions& socketTLSOptions,
96	        bool enablePong,
97	        int pingIntervalSecs)
98	    {
99	        _perMessageDeflateOptions = perMessageDeflateOptions;
100	        _enablePerMessageDeflate = _perMessageDeflateOptions.enabled();
101	        _socketTLSOptions = socketTLSOptions;
102	        _enablePong = enablePong;
103	        _pingIntervalSecs = pingIntervalSecs;
104	    }
105	
106	    void WebSocketTransport::resetReceiveState()
107	    {
108	        // A new connection must not inherit any receive state from a previous
109	        // connection on this object: no pending fragmented message content or
110	        // message kind, no stale compression attribute, no unparsed frame
111	        // bytes and no latched protocol error.
112	        _chunks.clear();
113	        _fragmentedMessageKind = MessageKind::MSG_TEXT;
114	        _receivedMessageCompressed = false;
115	        _protocolError = false;
116	        _rxbuf.clear();
117	        _rxbufWanted = 0;
118	    }
119	
120	    // Client
121	    WebSocketInitResult WebSocketTransport::connectToUrl(const std::string& url,
122	                                                         const WebSocketHttpHeaders& headers,
123	                                                         int timeoutSecs)
124	    {
125	        std::lock_guard<std::mutex> lock(_socketMutex);
126	
127	        std::string protocol, host, path, query;
128	        int port;
129	        std::string remoteUrl(url);
130	
131	        // A previous connection on this object might have been interrupted in
132	        // the middle of a fragmented message; start from a clean receive state.
133	        resetReceiveState();
134	
135	        WebSocketInitResult result;
136	        const int maxRedirections = 10;
137	
138	        for (int i = 0; i < maxRedirections; ++i)
139	        {
140	            if (!UrlParser::parse(remoteUrl, protocol, host, path, query, port))
141	            {
142	                std::stringstream ss;
143	                ss << "Could not parse url: '" << url << "'";
144	                return WebSocketInitResult(false, 0, ss.str());
145	            }
146	
147	            std::string errorMsg;
148	            bool tls = protocol == "wss";
149	            _socket = createSocket(tls, -1, errorMsg, _socketTLSOptions);
150	            _perMessageDeflate = ix::make_unique<WebSocketPerMessageDeflate>();
151	
152	            if (!_socket)
153	            {
154	                return WebSocketInitResult(false, 0, errorMsg);
155	            }
156	
157	            WebSocketHandshake webSocketHandshake(_requestInitCancellation,
158	                                                  _socket,
159	                                                  _perMessageDeflate,
160	                                                  _perMessageDeflateOptions,
161	                                                  _enablePerMessageDeflate);
162	
163	            result = webSocketHandshake.clientHandshake(
164	                remoteUrl, headers, protocol, host, path, port, timeoutSecs);
165	
166	            if (result.http_status >= 300 && result.http_status < 400)
167	            {
168	                auto it = result.headers.find("Location");
169	                if (it == result.headers.end())
170	                {
171	                    std::stringstream ss;
172	                    ss << "Missing Location Header for HTTP Redirect response. "
173	                       << "Rejecting connection to " << url << ", status: " << result.http_status;
174	                    result.errorStr = ss.str();
175	                    break;
176	                }
177	
178	                remoteUrl = it->second;
179	                continue;
180	            }
181	
182	            if (result.success)
183	            {
184	                setReadyState(ReadyState::OPEN);
185	            }
186	            return result;
187	        }
188	
189	        return result;
190	    }
191	
192	    // Server
193	    WebSocketInitResult WebSocketTransport::connectToSocket(std::unique_ptr<Socket> socket,
194	                                                            int timeoutSecs,
195	                                                            bool enablePerMessageDeflate,
196	                                                            HttpRequestPtr request,
197	                                                            int sendTimeoutSecs)
198	    {
199	        std::lock_guard<std::mutex> lock(_socketMutex);
200	
201	        // Server should not mask the data it sends to the client
202	        _useMask = false;
203	        _blockingSend = true;
204	        _sendTimeoutSecs = sendTimeoutSecs;
205	
206	        // A previous connection on this object might have been interrupted in
207	        // the middle of a fragmented message; start from a clean receive state.
208	        resetReceiveState();
209	
210	        _socket = std::move(socket);
211	        _perMessageDeflate = ix::make_unique<WebSocketPerMessageDeflate>();
212	
213	        WebSocketHandshake webSocketHandshake(_requestInitCancellation,
214	                                              _socket,
215	                                              _perMessageDeflate,
216	                                              _perMessageDeflateOptions,
217	                                              _enablePerMessageDeflate);
218	
219	        auto result =
220	            webSocketHandshake.serverHandshake(timeoutSecs, enablePerMessageDeflate, request);
221	        if (result.success)
222	        {
223	            setReadyState(ReadyState::OPEN);
224	        }
225	        return result;
226	    }
