904	
905	    WebSocketSendInfo WebSocketTransport::sendData(wsheader_type::opcode_type type,
906	                                                   const IXWebSocketSendData& message,
907	                                                   bool compress,
908	                                                   const OnProgressCallback& onProgressCallback)
909	    {
910	        if (_readyState != ReadyState::OPEN && _readyState != ReadyState::CLOSING)
911	        {
912	            return WebSocketSendInfo(false);
913	        }
914	
915	        size_t payloadSize = message.size();
916	        size_t wireSize = message.size();
917	        bool compressionError = false;
918	
919	        auto message_begin = message.cbegin();
920	        auto message_end = message.cend();
921	
922	        if (compress)
923	        {
924	            if (!_perMessageDeflate->compress(message, _compressedMessage))
925	            {
926	                bool success = false;
927	                compressionError = true;
928	                payloadSize = 0;
929	                wireSize = 0;
930	                return WebSocketSendInfo(success, compressionError, payloadSize, wireSize);
931	            }
932	            compressionError = false;
933	            wireSize = _compressedMessage.size();
934	
935	            IXWebSocketSendData compressedSendData(_compressedMessage);
936	            message_begin = compressedSendData.cbegin();
937	            message_end = compressedSendData.cend();
938	        }
939	
940	        {
941	            std::lock_guard<std::mutex> lock(_txbufMutex);
942	            _txbuf.reserve(wireSize);
943	        }
944	
945	        bool success = true;
946	
947	        // Common case for most message. No fragmentation required.
948	        if (wireSize < kChunkSize)
949	        {
950	            success = sendFragment(type, true, message_begin, message_end, compress);
951	
952	            if (onProgressCallback)
953	            {
954	                onProgressCallback(0, 1);
955	            }
956	        }
957	        else
958	        {
959	            //
960	            // Large messages need to be fragmented
961	            //
962	            // Rules:
963	            // First message needs to specify a proper type (BINARY or TEXT)
964	            // Intermediary and last messages need to be of type CONTINUATION
965	            // Last message must set the fin byte.
966	            //
967	            auto steps = wireSize / kChunkSize;
968	
969	            auto begin = message_begin;
970	            auto end = message_end;
971	
972	            for (uint64_t i = 0; i < steps; ++i)
973	            {
974	                bool firstStep = i == 0;
975	                bool lastStep = (i + 1) == steps;
976	                bool fin = lastStep;
977	
978	                end = begin + kChunkSize;
979	                if (lastStep)
980	                {
981	                    end = message_end;
982	                }
983	
984	                auto opcodeType = type;
985	                if (!firstStep)
986	                {
987	                    opcodeType = wsheader_type::CONTINUATION;
988	                }
989	
990	                // Send message
991	                if (!sendFragment(opcodeType, fin, begin, end, compress))
992	                {
993	                    return WebSocketSendInfo(false);
994	                }
995	
996	                if (onProgressCallback && !onProgressCallback((int) i, (int) steps))
997	                {
998	                    break;
999	                }
1000	
1001	                begin += kChunkSize;
1002	            }
1003	        }
1004	
1005	        // Request to flush the send buffer on the background thread if it isn't empty
1006	        if (!isSendBufferEmpty())
1007	        {
1008	            wakeUpFromPoll(SelectInterrupt::kSendRequest);
1009	
1010	            // FIXME: we should have a timeout when sending large messages: see #131
1011	            if (_blockingSend && !flushSendBuffer())
1012	            {
1013	                success = false;
1014	            }
1015	        }
1016	
1017	        return WebSocketSendInfo(success, compressionError, payloadSize, wireSize);
1018	    }
1019	
1020	    template<class Iterator>
1021	    bool WebSocketTransport::sendFragment(wsheader_type::opcode_type type,
1022	                                          bool fin,
1023	                                          Iterator message_begin,
1024	                                          Iterator message_end,
1025	                                          bool compress)
1026	    {
1027	        uint64_t message_size = static_cast<uint64_t>(message_end - message_begin);
1028	
1029	        unsigned x = getRandomUnsigned();
1030	        uint8_t masking_key[4] = {};
1031	        masking_key[0] = (x >> 24);
1032	        masking_key[1] = (x >> 16) & 0xff;
1033	        masking_key[2] = (x >> 8) & 0xff;
1034	        masking_key[3] = (x) &0xff;
1035	
1036	        std::vector<uint8_t> header;
1037	        header.assign(2 + (message_size >= 126 ? 2 : 0) + (message_size >= 65536 ? 6 : 0) +
1038	                          (_useMask ? 4 : 0),
1039	                      0);
1040	        header[0] = type;
1041	
1042	        // The fin bit indicate that this is the last fragment. Fin is French for end.
1043	        if (fin)
1044	        {
1045	            header[0] |= 0x80;
1046	        }
1047	
1048	        // The rsv1 bit indicate that the frame is compressed
1049	        // continuation opcodes should not set it. Autobahn 12.2.10 and others 12.X
1050	        if (compress && type != wsheader_type::CONTINUATION)
1051	        {
1052	            header[0] |= 0x40;
1053	        }
1054	
1055	        if (message_size < 126)
1056	        {
1057	            header[1] = (message_size & 0xff) | (_useMask ? 0x80 : 0);
1058	
1059	            if (_useMask)
1060	            {
1061	                header[2] = masking_key[0];
1062	                header[3] = masking_key[1];
1063	                header[4] = masking_key[2];
1064	                header[5] = masking_key[3];
1065	            }
1066	        }
1067	        else if (message_size < 65536)
1068	        {
1069	            header[1] = 126 | (_useMask ? 0x80 : 0);
1070	            header[2] = (message_size >> 8) & 0xff;
1071	            header[3] = (message_size >> 0) & 0xff;
1072	
1073	            if (_useMask)
1074	            {
1075	                header[4] = masking_key[0];
1076	                header[5] = masking_key[1];
1077	                header[6] = masking_key[2];
1078	                header[7] = masking_key[3];
1079	            }
1080	        }
1081	        else
1082	        { // TODO: run coverage testing here
1083	            header[1] = 127 | (_useMask ? 0x80 : 0);
1084	            header[2] = (message_size >> 56) & 0xff;
1085	            header[3] = (message_size >> 48) & 0xff;
1086	            header[4] = (message_size >> 40) & 0xff;
1087	            header[5] = (message_size >> 32) & 0xff;
1088	            header[6] = (message_size >> 24) & 0xff;
1089	            header[7] = (message_size >> 16) & 0xff;
1090	            header[8] = (message_size >> 8) & 0xff;
1091	            header[9] = (message_size >> 0) & 0xff;
1092	
1093	            if (_useMask)
1094	            {
1095	                header[10] = masking_key[0];
1096	                header[11] = masking_key[1];
1097	                header[12] = masking_key[2];
1098	                header[13] = masking_key[3];
1099	            }
1100	        }
1101	
1102	        // _txbuf will keep growing until it can be transmitted over the socket:
1103	        appendToSendBuffer(header, message_begin, message_end, message_size, masking_key);
1104	
1105	        // Now actually send this data
1106	        return sendOnSocket();
1107	    }
