1138	
1139	    bool WebSocketTransport::sendOnSocket()
1140	    {
1141	        std::lock_guard<std::mutex> lock(_txbufMutex);
1142	
1143	        while (_txbuf.size())
1144	        {
1145	            std::ptrdiff_t ret = 0;
1146	            {
1147	                std::lock_guard<std::mutex> lock(_socketMutex);
1148	                ret = _socket->send((char*) &_txbuf[0], _txbuf.size());
1149	            }
1150	
1151	            if (ret < 0 && Socket::isWaitNeeded())
1152	            {
1153	                break;
1154	            }
1155	            else if (ret <= 0)
1156	            {
1157	                closeSocket();
1158	                if (_readyState != ReadyState::CLOSING)
1159	                {
1160	                    setReadyState(ReadyState::CLOSED);
1161	                }
1162	                return false;
1163	            }
1164	            else
1165	            {
1166	                _txbuf.erase(_txbuf.begin(), _txbuf.begin() + ret);
1167	            }
1168	        }
1169	
1170	        return true;
1171	    }
1172	
1173	    bool WebSocketTransport::receiveFromSocket()
1174	    {
1175	        while (true)
1176	        {
1177	            // If _rxbufWanted isn't set, don't attempt to read more than kChunkSize
1178	            // into _rxbuf. If a client is sending frames faster than they can be
1179	            // processed this would otherwise bloat _rxbuf and further introduce
1180	            // unnecessary processing overhead due to .erase() in dispatch().
1181	            //
1182	            // Further, not reading everything from the socket will eventually
1183	            // result in back pressure for the client.
1184	            if (_rxbufWanted == 0 && _rxbuf.size() >= kChunkSize) break;
1185	
1186	            // There's also no point in reading more bytes than needed.
1187	            if (_rxbufWanted > 0 && _rxbuf.size() >= _rxbufWanted) break;
1188	
1189	            std::ptrdiff_t ret = _socket->recv((char*) &_readbuf[0], _readbuf.size());
1190	
1191	            if (ret < 0 && Socket::isWaitNeeded())
1192	            {
1193	                break;
1194	            }
1195	            else if (ret <= 0)
1196	            {
1197	                // if there are received data pending to be processed, then delay the abnormal
1198	                // closure to after dispatch (other close code/reason could be read from the
1199	                // buffer)
1200	
1201	                closeSocket();
1202	                return false;
1203	            }
1204	            else
1205	            {
1206	                _rxbuf.insert(_rxbuf.end(), _readbuf.begin(), _readbuf.begin() + ret);
1207	            }
1208	        }
1209	
1210	        return true;
1211	    }
1212	
1213	    void WebSocketTransport::sendCloseFrame(uint16_t code, const std::string& reason)
1214	    {
1215	        bool compress = false;
1216	
1217	        // if a status is set/was read
1218	        if (code != WebSocketCloseConstants::kNoStatusCodeErrorCode)
1219	        {
1220	            // See list of close events here:
1221	            // https://developer.mozilla.org/en-US/docs/Web/API/CloseEvent
1222	            std::string closure {(char) (code >> 8), (char) (code & 0xff)};
1223	
1224	            // copy reason after code
1225	            closure.append(reason);
1226	
1227	            sendData(wsheader_type::CLOSE, closure, compress);
1228	        }
1229	        else
1230	        {
1231	            // no close code/reason set
1232	            sendData(wsheader_type::CLOSE, std::string(""), compress);
1233	        }
1234	    }
