558	    WebSocketSendInfo WebSocket::ping(const std::string& text, SendMessageKind pingType)
559	    {
560	        // Standard limit ping message size
561	        constexpr size_t pingMaxPayloadSize = 125;
562	        if (text.size() > pingMaxPayloadSize) return WebSocketSendInfo(false);
563	
