566	
567	    WebSocketSendInfo WebSocket::sendMessage(const IXWebSocketSendData& message,
568	                                             SendMessageKind sendMessageKind,
569	                                             const OnProgressCallback& onProgressCallback)
570	    {
571	        if (!isConnected()) return WebSocketSendInfo(false);
572	
573	        //
574	        // It is OK to read and write on the same socket in 2 different threads.
575	        // https://stackoverflow.com/questions/1981372/are-parallel-calls-to-send-recv-on-the-same-socket-valid
576	        //
577	        // This makes it so that messages are sent right away, and we dont need
578	        // a timeout while we poll to keep wake ups to a minimum (which helps
579	        // with battery life), and use the system select call to notify us when
580	        // incoming messages are arriving / there's data to be received.
581	        //
582	        std::lock_guard<std::mutex> lock(_writeMutex);
583	        WebSocketSendInfo webSocketSendInfo;
584	
585	        switch (sendMessageKind)
586	        {
587	            case SendMessageKind::Text:
588	            {
589	                webSocketSendInfo = _ws.sendText(message, onProgressCallback);
590	            }
591	            break;
592	
593	            case SendMessageKind::Binary:
594	            {
595	                webSocketSendInfo = _ws.sendBinary(message, onProgressCallback);
596	            }
597	            break;
598	
599	            case SendMessageKind::Ping:
600	            {
601	                webSocketSendInfo = _ws.sendPing(message);
602	            }
603	            break;
604	        }
605	
606	        WebSocket::invokeTrafficTrackerCallback(webSocketSendInfo.wireSize, false);
607	
608	        return webSocketSendInfo;
609	    }
