617	            case ix::WebSocketTransport::ReadyState::CLOSING: return ReadyState::Closing;
618	            case ix::WebSocketTransport::ReadyState::CLOSED: return ReadyState::Closed;
619	            default: return ReadyState::Closed;
620	        }
621	    }
