        bool firstStep = i == 0;
        bool lastStep = (i + 1) == steps;
        bool fin = lastStep;

        end = begin + kChunkSize;
        if (lastStep)
        {
            end = message_end;
        }

        auto opcodeType = type;
        if (!firstStep)
        {
            opcodeType = wsheader_type::CONTINUATION;
        }

        // Send message
        if (!sendFragment(opcodeType, fin, begin, end, compress))
        {
            return WebSocketSendInfo(false);
        }

        if (onProgressCallback && !onProgressCallback((int) i, (int) steps))
        {
            // The send is only cancelled if the final fragment is
            // still missing. If the callback of the last fragment
            // returns false the message was fully committed and the
            // send is a success.
            sendCancelled = !lastStep;
            break;
        }

        begin += kChunkSize;
    }
