    closeSocket();
    setReadyState(ReadyState::CLOSED);
}

toolUseResult.newString:
// if we previously closed the connection (CLOSING state), then set state to CLOSED
// (code/reason were set before)
if (_readyState == ReadyState::CLOSING)
{
    closeSocket();
    clearSendBuffer();
    setReadyState(ReadyState::CLOSED);
}

toolUseResult.oldString:
else if (ret <= 0)
{
    closeSocket();
    if (_readyState != ReadyState::CLOSING)
    {
        setReadyState(ReadyState::CLOSED);
    }
    return false;
}

toolUseResult.newString:
else if (ret <= 0)
{
    closeSocket();
    // The socket is closed: pending outgoing bytes can never be
    // sent. (_txbufMutex is held by this method.)
    _txbuf.clear();
    if (_readyState != ReadyState::CLOSING)
    {
        setReadyState(ReadyState::CLOSED);
    }
    return false;
}

